use rusqlite::{params, Connection, OptionalExtension, Transaction};
pub fn install_schema(tx:&Transaction<'_>)->rusqlite::Result<()> {tx.execute_batch("CREATE TABLE IF NOT EXISTS project_knowledge_notebook (notebook_id TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, json BLOB NOT NULL, idempotency_key TEXT NOT NULL, updated_at_ms INTEGER NOT NULL, PRIMARY KEY(notebook_id,revision), UNIQUE(notebook_id,idempotency_key)); CREATE TABLE IF NOT EXISTS project_knowledge_notebook_pin (run_id TEXT PRIMARY KEY, notebook_id TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, pinned_at_ms INTEGER NOT NULL);")}
pub fn save(c:&Connection,id:&str,revision:u64,hash:&str,json:&[u8],key:&str,now:i64)->rusqlite::Result<()> {let prior:Option<(u64,String)>=c.query_row("SELECT revision,content_hash FROM project_knowledge_notebook WHERE notebook_id=?1 AND idempotency_key=?2",params![id,key],|r|Ok((r.get(0)?,r.get(1)?))).optional()?;if let Some((r,h))=prior{if r==revision&&h==hash{return Ok(())}return Err(rusqlite::Error::InvalidParameterName("notebook idempotency conflict".into()))}let current:Option<u64>=c.query_row("SELECT MAX(revision) FROM project_knowledge_notebook WHERE notebook_id=?1",params![id],|r|r.get(0)).optional()?.flatten();if revision!=current.unwrap_or(0)+1{return Err(rusqlite::Error::InvalidParameterName("notebook revision conflict".into()))}c.execute("INSERT INTO project_knowledge_notebook VALUES(?1,?2,?3,?4,?5,?6)",params![id,revision,hash,json,key,now])?;Ok(())}
pub fn current(c:&Connection,id:&str)->rusqlite::Result<Option<Vec<u8>>>{c.query_row("SELECT json FROM project_knowledge_notebook WHERE notebook_id=?1 ORDER BY revision DESC LIMIT 1",params![id],|r|r.get(0)).optional()}
pub fn pin(c:&Connection,run_id:&str,id:&str,revision:u64,hash:&str,now:i64)->rusqlite::Result<()> {let prior:Option<(String,u64,String)>=c.query_row("SELECT notebook_id,revision,content_hash FROM project_knowledge_notebook_pin WHERE run_id=?1",params![run_id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional()?;if let Some((pid,pr,ph))=prior{if pid==id&&pr==revision&&ph==hash{return Ok(())}return Err(rusqlite::Error::InvalidParameterName("notebook run already pinned".into()))}c.execute("INSERT INTO project_knowledge_notebook_pin VALUES(?1,?2,?3,?4,?5)",params![run_id,id,revision,hash,now])?;Ok(())}
